/* ============================================================
   RECEIPT LOGOS (base64-embedded so PDF receipts work offline
   and without extra network requests when generating with jsPDF)
   ============================================================ */

/* Receipt header background (wave image) — first page and following pages */
const RECEIPT_HEADER_FIRST = "data:image/jpeg;base64,";
const RECEIPT_HEADER_NEXT  = "data:image/jpeg;base64,";

/* ===== SF logo used in every downloaded receipt (cut from the brand header image) ===== */
const LOGO_SF_RECEIPT = "data:image/png;base64,";
const LOGO_SF_RATIO = 1.5606;

/* Receipt header: white top + blue wave ribbon, then  [SF logo] | Name / calendar date | clock time  */
function drawReceiptHeader(doc, W, isFirst, titleText, today) {
  const headerH = isFirst ? 28 : 18;
  const k = headerH / 28;                       // scale vs the first-page header
  const navy = [8, 24, 170];

  try { doc.addImage(isFirst ? RECEIPT_HEADER_FIRST : RECEIPT_HEADER_NEXT, 'JPEG', 0, 0, W, headerH); }
  catch (e) { doc.setFillColor(225, 241, 255); doc.rect(0, headerH - 6, W, 6, 'F'); }

  // logo
  const logoH = 14.6 * k, logoY = 2.2 * k, logoX = W * 0.095;
  try {
    const lp = doc.getImageProperties(LOGO_SF_RECEIPT);
    doc.addImage(LOGO_SF_RECEIPT, 'PNG', logoX, logoY, logoH * lp.width / lp.height, logoH);
  } catch (e) {}

  // divider
  const divX = W * 0.275;
  doc.setDrawColor(40, 60, 200); doc.setLineWidth(0.5);
  doc.line(divX, 2.5 * k, divX, 15.1 * k);

  // name (shrinks to fit) + date/time line centred under it
  const tx = W * 0.34, maxW = W * 0.78 - tx;
  const name = String(titleText || '');
  let fs = 20 * k + (isFirst ? 0 : 0.5);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(fs);
  while (doc.getTextWidth(name) > maxW && fs > 8) { fs -= 0.5; doc.setFontSize(fs); }
  const nw = doc.getTextWidth(name);

  const now = new Date();
  const dateTxt = now.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  const timeTxt = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
  const dfs = 11 * k + (isFirst ? 0 : 0.8);
  doc.setFont('helvetica', 'normal'); doc.setFontSize(dfs);
  const iz = 3.8 * k + (isFirst ? 0 : 0.3), g = 1.6;
  const dW = doc.getTextWidth(dateTxt), tW = doc.getTextWidth(timeTxt);
  const dw = iz + g + dW + 3.2 + iz + g + tW;
  const bw = Math.max(nw, dw);

  // name
  doc.setFont('helvetica', 'bold'); doc.setFontSize(fs); doc.setTextColor(navy[0], navy[1], navy[2]);
  doc.text(name, tx + (bw - nw) / 2, 0.2 * headerH + (0.72 * fs * 0.3528) / 2);

  // date line
  let x = tx + (bw - dw) / 2;
  const cy = 0.43 * headerH, iy = cy - iz / 2, base = cy + dfs * 0.3528 * 0.36;
  doc.setDrawColor(navy[0], navy[1], navy[2]); doc.setLineWidth(0.3);
  // calendar icon
  doc.roundedRect(x, iy + iz * 0.12, iz, iz * 0.88, 0.5, 0.5, 'S');
  doc.line(x, iy + iz * 0.38, x + iz, iy + iz * 0.38);
  doc.line(x + iz * 0.3, iy, x + iz * 0.3, iy + iz * 0.2);
  doc.line(x + iz * 0.7, iy, x + iz * 0.7, iy + iz * 0.2);
  x += iz + g;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(dfs);
  doc.text(dateTxt, x, base);
  x += dW + 1.6;
  doc.line(x, iy, x, iy + iz);                  // thin separator
  x += 1.6;
  // clock icon + time
  doc.circle(x + iz / 2, cy, iz / 2, 'S');
  doc.line(x + iz / 2, cy, x + iz / 2, cy - iz * 0.32);
  doc.line(x + iz / 2, cy, x + iz * 0.5 + iz * 0.24, cy + iz * 0.12);
  x += iz + g;
  doc.text(timeTxt, x, base);

  doc.setTextColor(0, 0, 0);
}

