function waveD(seg, y, dy, closeTo) {
  let d = 'M0 ' + y + ' Q' + (seg / 2) + ' ' + (y + dy) + ' ' + seg + ' ' + y;
  for (let x = seg; x < 2880;) { x += seg; d += ' T' + x + ' ' + y; }
  return d + (closeTo === 'down' ? ' V160 H0 Z' : (closeTo === 'card' ? ' V100 H0 Z' : ' V0 H0 Z'));
}

/* two slow waves at the bottom of a Receivables-style card */
