/* ===== Accounts carousel + records cards (used on the main page and every menu page) ===== */
const REC_DOC_ICON = '<svg viewBox="0 0 28 28" fill="currentColor"><path d="M8 2h8l5 5v9a3 3 0 0 1-3 3H8a3 3 0 0 1-3-3V5a3 3 0 0 1 3-3z" opacity=".5"/><path d="M12 9h8l5 5v9a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3V12a3 3 0 0 1 3-3z"/><rect x="13" y="17" width="9" height="2" rx="1" fill="#fff"/><rect x="13" y="21" width="6" height="2" rx="1" fill="#fff"/></svg>';
const ACC_NAV_HTML =
  '<div class="acc-nav is-hidden">' +
  '<button type="button" class="acc-prev" aria-label="Previous accounts"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5l-7 7 7 7"/></svg></button>' +
  '<button type="button" class="acc-next" aria-label="Next accounts"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5l7 7-7 7"/></svg></button>' +
  '</div>';

function setupAccountsCarousel(sec, area) {
  const nav  = sec.querySelector('.acc-nav');
  const prev = nav.querySelector('.acc-prev');
  const next = nav.querySelector('.acc-next');
  let lastLeft = 0;

  const grid = () => area.querySelector('.student-grid');
  const stepPx = (g) => {
    const c = g.querySelector('.student-account-card');
    if (!c) return g.clientWidth;
    const gap = parseFloat(getComputedStyle(g).columnGap) || 12;
    const per = c.offsetWidth + gap;
    return Math.max(1, Math.floor(g.clientWidth / per)) * per;   // one "page" = the cards that are visible now
  };

  function update() {
    const g = grid();
    const track = area.querySelector('.acc-progress');
    if (!g) { nav.classList.add('is-hidden'); return; }
    const max = g.scrollWidth - g.clientWidth;
    const scrollable = max > 4;
    nav.classList.toggle('is-hidden', !scrollable);
    prev.disabled = g.scrollLeft <= 2;
    next.disabled = g.scrollLeft >= max - 2;
    if (track) {
      track.classList.toggle('is-hidden', !scrollable);
      const thumb = track.firstElementChild;
      const tw = track.clientWidth;
      const w = Math.max(36, tw * g.clientWidth / Math.max(1, g.scrollWidth));
      thumb.style.width = w + 'px';
      thumb.style.transform = 'translateX(' + (max > 0 ? (g.scrollLeft / max) * (tw - w) : 0) + 'px)';
    }
  }

  function bind(g) {
    if (g.dataset.bound) return;
    g.dataset.bound = '1';
    g.addEventListener('scroll', () => { lastLeft = g.scrollLeft; update(); }, { passive: true });
    // drag with the mouse (touch screens already swipe natively)
    let down = false, moved = false, sx = 0, sl = 0;
    g.addEventListener('pointerdown', (e) => {
      if (e.pointerType !== 'mouse' || e.button !== 0 || e.target.closest('button')) return;
      down = true; moved = false; sx = e.clientX; sl = g.scrollLeft;
    });
    g.addEventListener('pointermove', (e) => {
      if (!down) return;
      const dx = e.clientX - sx;
      if (!moved && Math.abs(dx) > 4) { moved = true; g.classList.add('dragging'); }
      if (moved) g.scrollLeft = sl - dx;
    });
    const end = () => { down = false; g.classList.remove('dragging'); };
    g.addEventListener('pointerup', end);
    g.addEventListener('pointerleave', end);
    g.addEventListener('pointercancel', end);
  }

  function onChange() {
    const g = grid();
    if (g) {
      if (!area.querySelector('.acc-progress')) area.insertAdjacentHTML('beforeend', '<div class="acc-progress"><span></span></div>');
      bind(g);
      g.scrollLeft = lastLeft;            // keep the position after a re-render
    } else {
      lastLeft = 0;
    }
    update();
  }

  prev.addEventListener('click', () => { const g = grid(); if (g) g.scrollBy({ left: -stepPx(g), behavior: 'smooth' }); });
  next.addEventListener('click', () => { const g = grid(); if (g) g.scrollBy({ left:  stepPx(g), behavior: 'smooth' }); });

  new MutationObserver(onChange).observe(area, { childList: true });
  if (window.ResizeObserver) new ResizeObserver(update).observe(area);   // also fires when a hidden page is opened
  else window.addEventListener('resize', update);
  onChange();
}

function decorateRecordCards(root) {
  (root || document).querySelectorAll('section.card').forEach(sec => {
    if (sec.dataset.recStyled) return;
    const hd = sec.querySelector(':scope > .records-header');
    if (!hd) return;
    const accArea = sec.querySelector('[id$="AccountsArea"]');
    const tblArea = sec.querySelector('[id$="ableArea"]');
    if (!accArea && !tblArea) return;
    sec.dataset.recStyled = '1';
    sec.classList.add('rec-card', accArea ? 'rec-accounts' : 'rec-records');
    hd.insertAdjacentHTML('afterbegin', '<span class="rh-icon" aria-hidden="true">' + (accArea ? RCV_ICONS.users : REC_DOC_ICON) + '</span>');
    if (accArea) {
      hd.insertAdjacentHTML('beforeend', ACC_NAV_HTML);
      setupAccountsCarousel(sec, accArea);
    }
  });
}

function decoratePageHeader(root) {
  if (!root) return;
  const hd = root.querySelector('.myself-page-header');
  if (!hd || hd.dataset.styled) return;
  hd.dataset.styled = '1';
  hd.insertAdjacentHTML('afterbegin', pageHeaderArtHTML());
  const brand = '<img class="pg-logo" src="assets/spendflow-logo.png" alt="SpendFlow"/><i class="hd-div" aria-hidden="true"></i>';
  const h1 = hd.querySelector('h1');
  if (h1) h1.insertAdjacentHTML('beforebegin', brand);
  else hd.querySelector('.hd-art').insertAdjacentHTML('afterend', brand);
  const closeBtn = hd.querySelector('.btn-close-myself');
  if (closeBtn) {
    closeBtn.innerHTML = RCV_ICONS.close;
    closeBtn.setAttribute('aria-label', 'Close');
    closeBtn.setAttribute('title', 'Close');
    if (hd.querySelector('.header-search')) closeBtn.insertAdjacentHTML('beforebegin', '<i class="hd-div hd-div-sm" aria-hidden="true"></i>');
  }
}


