function wrapMultiline(doc, text, width) {
  const out = [];
  String(text == null ? '' : text).split(/\r\n|\r|\n/).forEach(line => {
    if (line === '') { out.push(''); return; }
    out.push(...doc.splitTextToSize(line, width));
  });
  return out.length ? out : [''];
}

function esc(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function escAttr(s) {
  return String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
}

/* ============================================================
   PDF GENERATION
   ============================================================ */

// Download all records (or the currently filtered set) as one PDF
function downloadAllPDF() {
  const list = currentFilter
    ? records.filter(r => r.lender.trim().toLowerCase() === currentFilter.toLowerCase())
    : records;
  const title = currentFilter ? currentFilter + "'s Debt Receipt" : 'Student Debt Receipt';
  const filePrefix = currentFilter ? currentFilter.replace(/\s+/g, '_') + '_Receipt' : 'Receipt_list_FM';
  buildPDF(list, title, filePrefix);
}

// Download a single student's records only, regardless of current filter
function downloadStudentPDF(studentName) {
  const list = records.filter(r => r.lender.trim().toLowerCase() === studentName.toLowerCase());
  if (list.length === 0) return;
  const title = studentName + "'s Debt Receipt";
  const filePrefix = studentName.replace(/\s+/g, '_') + '_Receipt';
  buildPDF(list, title, filePrefix);
}

function buildPDF(recordsList, titleText, filenamePrefix) {
  if (recordsList.length === 0) return;

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : r.amount), 0);

  // Column definitions — reason gets remaining space
  // #, Borrower, Lender, Amount, Date/Time, Reason
  const cols = [
    { x: margin,      w: 10  },  // #
    { x: margin + 10, w: 38  },  // Borrower
    { x: margin + 48, w: 38  },  // Lender
    { x: margin + 86, w: 28  },  // Amount
    { x: margin + 114,w: 28  },  // Date/Time
    { x: margin + 142,w: W - margin - 142 - margin }  // Reason — full remaining width
  ];
  const headers = ['No.', 'Name', "Boy's Name", 'Amount', 'Date / Time', 'Reason'];

  // ---- Page header function (called on each new page) ----
  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  // ---- Summary box ----
  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 33, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 41);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  doc.text('Total Debt: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 41, { align: 'right' });

  let y = 52;

  // ---- Draw table header row ----
  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  // ---- Rows ---- (oldest first → serial 1,2,3,4...)
  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    // Calculate row height based on wrapped reason text
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[5].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    // New page check
    if (y + rowH > H - 20) {
      // Footer on current page
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 24;
      drawTableHeader();
    }

    // Row background
    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    // #
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    // Borrower
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.student, cols[1].w - 4), cols[1].x + 2, midY);

    // Lender
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(50, 50, 50);
    doc.text(doc.splitTextToSize(r.lender, cols[2].w - 4), cols[2].x + 2, midY);

    // Amount
    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(8);
    doc.setTextColor(0, 110, 182);
    const amountText = 'Rs. ' + r.amount.toLocaleString('en-PK');
    doc.text(amountText, cols[3].x + 2, midY);
    if (r.struck) {
      const tw = doc.getTextWidth(amountText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[3].x + 2, midY - 1.3, cols[3].x + 2 + tw, midY - 1.3);
    }

    // Date / Time
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[4].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[4].x + 2, y + rowH / 2 + 4);

    // Reason — fully wrapped, no truncation
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[5].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'receivables' });
  doc.save(filenamePrefix + '_' + today.replace(/\//g, '-') + '.pdf');

  function drawPageFooter() {
    doc.setDrawColor(26, 58, 92);
    doc.setLineWidth(0.4);
    doc.line(margin, H - 12, W - margin, H - 12);
    doc.setTextColor(140, 140, 140);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 7, { align: 'center' });
  }
}

/* ============================================================
   MY OWN ACCOUNT — money the logged-in user borrowed from others
   (kept in a separate localStorage key from the main records)
   ============================================================ */
function addOwnRecord() {
  const from    = document.getElementById('ownFromName').value.trim();
  const amount  = parseFloat(document.getElementById('ownAmount').value);
  const date    = document.getElementById('ownDate').value;
  const timeRaw = document.getElementById('ownTime').value;
  const time    = convertTo12hr(timeRaw);
  const reason  = document.getElementById('ownReason').value.trim();

  if (!from)   { alert('Plz enter who you borrowed from.'); return; }
  if (!amount || amount <= 0) { alert('Plz enter a valid amount.'); return; }
  if (!date)   { alert('Plz select a date.'); return; }
  if (!reason) { alert('Plz enter a reason.'); return; }

  ownRecords.unshift({ id: Date.now(), from, amount, date, time, reason });
  trackEvent('add_entry', { section: 'main' });
  saveOwn();
  renderOwnAccounts();
  renderOwnTable();
  resetOwnForm();
  showToast();
}

function saveOwn() {
  if (!currentAccountKey) return;
  accountDocRef(currentAccountKey).set({ myOwnDebt: ownRecords }, { merge: true })
    .catch(err => console.error('Save failed:', err));
}

function deleteOwnRecord(id) {
  if (!confirm('Move this record to Trash?')) return;
  const r = ownRecords.find(x => x.id === id);
  if (!r) return;
  ownRecords = ownRecords.filter(x => x.id !== id);
  trashItems.unshift({ ...r, _type: 'own' });
  saveOwn();
  saveTrash();
  renderOwnAccounts();
  renderOwnTable();
}

function resetOwnForm() {
  document.getElementById('ownAmount').value = '';
  document.getElementById('ownReason').value = '';
  const now = new Date();
  document.getElementById('ownDate').value = now.toISOString().split('T')[0];
  document.getElementById('ownTime').value = now.toTimeString().slice(0, 5);
}

/* ============================================================
   MY ACCOUNT SEARCH — searches only within "My Account" names
   ============================================================ */
function initOwnSearch() {
  const toggleBtn = document.getElementById('ownSearchToggleBtn');
  const box       = document.getElementById('ownSearchBox');
  const input     = document.getElementById('ownSearchInput');
  const results   = document.getElementById('ownSearchResults');
  const wrap      = document.getElementById('ownSearchWrap');

  toggleBtn.addEventListener('click', () => {
    const isHidden = box.style.display === 'none';
    box.style.display = isHidden ? 'block' : 'none';
    if (isHidden) {
      input.value = '';
      results.innerHTML = '';
      input.focus();
    }
  });

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    if (!q) { results.innerHTML = ''; return; }

    const matches = getOwnGroups().filter(g => g.name.toLowerCase().includes(q));

    if (matches.length === 0) {
      results.innerHTML = '<div class="search-empty">No matching account found.</div>';
      return;
    }

    results.innerHTML = matches.map(g => `
      <div class="search-result-item" onclick="selectOwnSearchResult('${escAttr(g.name)}')">
        <span class="search-result-name">${esc(g.name)}</span>
        <span class="search-result-total">Rs. ${g.total.toLocaleString('en-PK')}</span>
      </div>
    `).join('');
  });

  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) box.style.display = 'none';
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') box.style.display = 'none';
  });
}

function selectOwnSearchResult(name) {
  document.getElementById('ownSearchBox').style.display = 'none';
  filterByOwnPerson(name);
}

/* ---- Grouped by the person the money was borrowed from ---- */
function getOwnGroups() {
  const groups = {};
  ownRecords.forEach(r => {
    const key = r.from.trim().toLowerCase();
    if (!groups[key]) groups[key] = { name: r.from.trim(), total: 0, count: 0 };
    if (!r.struck) groups[key].total += r.amount;
    groups[key].count += 1;
  });
  // Keep insertion order (newest entry first) instead of sorting by total.
  return Object.values(groups);
}

function renderOwnAccounts() {
  const area  = document.getElementById('ownAccountsArea');
  const badge = document.getElementById('ownStudentCountBadge');
  const groups = getOwnGroups();

  badge.textContent = groups.length + ' People';

  if (groups.length === 0) {
    area.innerHTML = '<div class="empty-state">You have not added anyone yet.</div>';
    return;
  }

  let html = '<div class="student-grid">';
  groups.forEach(g => {
    const isActive = ownCurrentFilter && ownCurrentFilter.toLowerCase() === g.name.toLowerCase();
    html += `<div class="student-account-card${isActive ? ' active' : ''}">
      <div class="student-account-name">${esc(g.name)}</div>
      <div class="student-account-meta">${g.count} ${g.count === 1 ? 'entry' : 'entries'}</div>
      <div class="student-account-total">Rs. ${g.total.toLocaleString('en-PK')}</div>
      <div class="student-account-actions">
        <button class="btn-view" onclick="filterByOwnPerson('${escAttr(g.name)}')">View List</button>
        <button class="btn-student-download" onclick="downloadOwnPersonPDF('${escAttr(g.name)}')">Download</button>
      </div>
    </div>`;
  });
  html += '</div>';
  area.innerHTML = html;
}

function filterByOwnPerson(name) {
  ownCurrentFilter = name;
  renderOwnAccounts();
  renderOwnTable();
  document.getElementById('ownTableArea').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function clearOwnFilter() {
  ownCurrentFilter = null;
  renderOwnAccounts();
  renderOwnTable();
}

function renderOwnTable() {
  const area     = document.getElementById('ownTableArea');
  const badge    = document.getElementById('ownCountBadge');
  const bar      = document.getElementById('ownTotalBar');
  const dlBtn    = document.getElementById('ownDownloadAllBtn');
  const clearBtn = document.getElementById('ownClearFilterBtn');
  const titleEl  = document.getElementById('ownRecordsTitle');
  const totalLabelEl = document.getElementById('ownTotalLabel');

  const visible = ownCurrentFilter
    ? ownRecords.filter(r => r.from.trim().toLowerCase() === ownCurrentFilter.toLowerCase())
    : ownRecords;

  if (ownCurrentFilter) {
    titleEl.textContent = 'Repaid ' + ownCurrentFilter;
    totalLabelEl.textContent = 'Total Owed to ' + ownCurrentFilter;
    if (clearBtn) clearBtn.style.display = 'inline-block';
    dlBtn.textContent = 'Download ' + ownCurrentFilter + "'s Receipt";
    dlBtn.onclick = () => downloadOwnPersonPDF(ownCurrentFilter);
  } else {
    titleEl.textContent = 'My Loan History';
    totalLabelEl.textContent = 'Total Borrowed';
    if (clearBtn) clearBtn.style.display = 'none';
    dlBtn.textContent = 'Download All Receipt';
    dlBtn.onclick = () => downloadOwnAllPDF();
  }

  badge.textContent = visible.length + ' Records';

  if (visible.length === 0) {
    area.innerHTML = '<div class="empty-state">No records added yet.</div>';
    bar.style.display = 'none';
    dlBtn.style.display = 'none';
    return;
  }

  const total = visible.reduce((s, r) => s + (r.struck ? 0 : r.amount), 0);
  document.getElementById('ownTotalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
  bar.style.display = 'flex';
  dlBtn.style.display = 'inline-block';

  let rows = '';
  visible.forEach((r, i) => {
    const serial = visible.length - i;
    rows += `<tr>
      <td class="td-muted">${serial}</td>
      <td class="td-bold">${esc(r.from)}</td>
      <td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amount.toLocaleString('en-PK')}</td>
      <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
      <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="toggleOwnStrike(${r.id})" title="Mark as settled"/></td>
      <td><button class="btn-del" onclick="deleteOwnRecord(${r.id})">Delete</button></td>
    </tr>`;
  });

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>Repaid</th><th class="th-blue">Amount</th><th>Reason</th><th>Date / Time</th><th>Paid</th><th></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function toggleOwnStrike(id) {
  const r = ownRecords.find(x => x.id === id);
  if (!r) return;
  r.struck = !r.struck;
  saveOwn();
  renderOwnTable();
  renderOwnAccounts();
}

/* ---- PDF for own borrowed money ---- */
function downloadOwnAllPDF() {
  const list = ownCurrentFilter
    ? ownRecords.filter(r => r.from.trim().toLowerCase() === ownCurrentFilter.toLowerCase())
    : ownRecords;
  const title = ownCurrentFilter ? 'Payment Return to ' + ownCurrentFilter : 'My Loans Receipt';
  const filePrefix = ownCurrentFilter ? ownCurrentFilter.replace(/\s+/g, '_') + '_Owed_Receipt' : 'My_Loans_Receipt';
  buildOwnPDF(list, title, filePrefix);
}

function downloadOwnPersonPDF(personName) {
  const list = ownRecords.filter(r => r.from.trim().toLowerCase() === personName.toLowerCase());
  if (list.length === 0) return;
  const title = 'Payment Return to ' + personName;
  const filePrefix = personName.replace(/\s+/g, '_') + '_Owed_Receipt';
  buildOwnPDF(list, title, filePrefix);
}

function buildOwnPDF(recordsList, titleText, filenamePrefix, opts) {
  if (recordsList.length === 0) return;
  const noAmount = !!(opts && opts.noAmount);   // 'Item Return' receipts: no Amount column, no Total Loan

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : (r.amount || 0)), 0);

  // Columns: #, Repayment, Amount, Date/Time, Reason  (Item Return: no Amount column)
  const cols = noAmount ? [
    { x: margin,       w: 10 },
    { x: margin + 10,  w: 56 },
    { x: margin + 66,  w: 30 },
    { x: margin + 96,  w: W - margin - 96 - margin }
  ] : [
    { x: margin,       w: 10 },
    { x: margin + 10,  w: 46 },
    { x: margin + 56,  w: 30 },
    { x: margin + 86,  w: 30 },
    { x: margin + 116, w: W - margin - 116 - margin }
  ];
  const repayLabel = (opts && opts.repayLabel) || 'Repayment';
  const reasonLabel = (opts && opts.reasonLabel) || 'Reason';
  const headers = noAmount ? ['No.', repayLabel, 'Date / Time', reasonLabel] : ['No.', repayLabel, 'Amount', 'Date / Time', reasonLabel];
  const dateCol = noAmount ? 2 : 3;
  const reasonCol = noAmount ? 3 : 4;

  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 33, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 41);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  if (!noAmount) doc.text('Total Loan: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 41, { align: 'right' });

  let y = 52;

  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[reasonCol].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    if (y + rowH > H - 20) {
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 24;
      drawTableHeader();
    }

    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.from, cols[1].w - 4), cols[1].x + 2, midY);

    if (!noAmount) {
      doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
      doc.setFontSize(8);
      doc.setTextColor(0, 110, 182);
      const amountText = 'Rs. ' + r.amount.toLocaleString('en-PK');
      doc.text(amountText, cols[2].x + 2, midY);
      if (r.struck) {
        const tw = doc.getTextWidth(amountText);
        doc.setDrawColor(0, 0, 0);
        doc.setLineWidth(0.35);
        doc.line(cols[2].x + 2, midY - 1.3, cols[2].x + 2 + tw, midY - 1.3);
      }
    }

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[dateCol].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[dateCol].x + 2, y + rowH / 2 + 4);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[reasonCol].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'main' });
  doc.save(filenamePrefix + '_' + today.replace(/\//g, '-') + '.pdf');

  function drawPageFooter() {
    doc.setDrawColor(26, 58, 92);
    doc.setLineWidth(0.4);
    doc.line(margin, H - 12, W - margin, H - 12);
    doc.setTextColor(140, 140, 140);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 7, { align: 'center' });
  }
}
/* ============================================================
   ADVANCE ACCOUNTS — money given to people that they still owe
   back (kept in a separate Firestore field from the main and
   own records, mirroring the same pattern)
   ============================================================ */
/* Amount Taken / Amount Price / Amount Remaining auto-calculation:
   Price + Remaining = Taken. Typing in one of Price / Remaining fills the other. */
let advanceLastEdited = null; // 'price' | 'remaining'
function advRound(n) { return Math.round(n * 100) / 100; }
function advGetPrice(r) {
  if (typeof r.amountPrice === 'number') return r.amountPrice;
  return advRound((r.amountTaken || 0) - (r.amountRemaining || 0)); // older records
}
function initAdvanceAutoCalc() {
  const takenEl = document.getElementById('advanceAmountTaken');
  const priceEl = document.getElementById('advanceAmountPrice');
  const remEl   = document.getElementById('advanceAmountRemaining');
  if (!takenEl || !priceEl || !remEl) return;

  function fromPrice() {
    const t = parseFloat(takenEl.value), p = parseFloat(priceEl.value);
    remEl.value = (isNaN(t) || isNaN(p)) ? '' : advRound(t - p);
  }
  function fromRemaining() {
    const t = parseFloat(takenEl.value), r = parseFloat(remEl.value);
    priceEl.value = (isNaN(t) || isNaN(r)) ? '' : advRound(t - r);
  }
  priceEl.addEventListener('input', () => { advanceLastEdited = 'price'; fromPrice(); });
  remEl.addEventListener('input',   () => { advanceLastEdited = 'remaining'; fromRemaining(); });
  takenEl.addEventListener('input', () => {
    if (advanceLastEdited === 'price') fromPrice();
    else if (advanceLastEdited === 'remaining') fromRemaining();
  });
}

function addAdvanceRecord() {
  const name            = document.getElementById('advanceName').value.trim();
  const otherName       = document.getElementById('advanceOtherName').value.trim();
  const amountTaken     = parseFloat(document.getElementById('advanceAmountTaken').value);
  const amountPriceRaw  = document.getElementById('advanceAmountPrice').value;
  const amountPrice     = amountPriceRaw === '' ? NaN : parseFloat(amountPriceRaw);
  const amountRemainingRaw = document.getElementById('advanceAmountRemaining').value;
  let amountRemaining   = amountRemainingRaw === '' ? NaN : parseFloat(amountRemainingRaw);
  const date    = document.getElementById('advanceDate').value;
  const timeRaw = document.getElementById('advanceTime').value;
  const time    = convertTo12hr(timeRaw);
  const reason  = document.getElementById('advanceReason').value.trim();

  if (!name)      { alert('Plz enter the name.'); return; }
  if (!otherName) { alert('Plz enter the other name.'); return; }
  if (!amountTaken || amountTaken <= 0) { alert('Plz enter a valid amount taken.'); return; }
  if (isNaN(amountPrice) && isNaN(amountRemaining)) { alert('Plz enter the amount price.'); return; }
  let price = amountPrice;
  if (isNaN(price)) price = advRound(amountTaken - amountRemaining);
  if (isNaN(amountRemaining)) amountRemaining = advRound(amountTaken - price);
  if (price < 0 || amountRemaining < 0) { alert('Amount Price cannot be more than Amount Taken.'); return; }
  if (!date)     { alert('Plz select a date.'); return; }
  if (!timeRaw)  { alert('Plz select a time.'); return; }
  if (!reason)   { alert('Plz enter a reason.'); return; }

  advanceRecords.unshift({ id: Date.now(), name, otherName, amountTaken, amountPrice: price, amountRemaining, date, time, reason });
  trackEvent('add_entry', { section: 'tasks' });
  saveAdvance();
  renderAdvanceAccounts();
  renderAdvanceTable();
  resetAdvanceForm();
  showToast();
}

function saveAdvance() {
  if (!currentAccountKey) return;
  accountDocRef(currentAccountKey).set({ myAdvanceDebt: advanceRecords }, { merge: true })
    .catch(err => console.error('Save failed:', err));
}

function deleteAdvanceRecord(id) {
  if (!confirm('Move this record to Trash?')) return;
  const r = advanceRecords.find(x => x.id === id);
  if (!r) return;
  advanceRecords = advanceRecords.filter(x => x.id !== id);
  trashItems.unshift({ ...r, _type: 'advance' });
  saveAdvance();
  saveTrash();
  renderAdvanceAccounts();
  renderAdvanceTable();
}

function resetAdvanceForm() {
  document.getElementById('advanceAmountTaken').value = '';
  document.getElementById('advanceAmountPrice').value = '';
  document.getElementById('advanceAmountRemaining').value = '';
  advanceLastEdited = null;
  document.getElementById('advanceReason').value = '';
  const now = new Date();
  document.getElementById('advanceDate').value = now.toISOString().split('T')[0];
  document.getElementById('advanceTime').value = now.toTimeString().slice(0, 5);
}

/* ============================================================
   ADVANCE SEARCH — searches only within "Tasks" names
   ============================================================ */
function initAdvanceSearch() {
  const toggleBtn = document.getElementById('advanceSearchToggleBtn');
  const box       = document.getElementById('advanceSearchBox');
  const input     = document.getElementById('advanceSearchInput');
  const results   = document.getElementById('advanceSearchResults');
  const wrap      = document.getElementById('advanceSearchWrap');

  toggleBtn.addEventListener('click', () => {
    const isHidden = box.style.display === 'none';
    box.style.display = isHidden ? 'block' : 'none';
    if (isHidden) {
      input.value = '';
      results.innerHTML = '';
      input.focus();
    }
  });

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    if (!q) { results.innerHTML = ''; return; }

    const matches = getAdvanceGroups().filter(g => g.name.toLowerCase().includes(q));

    if (matches.length === 0) {
      results.innerHTML = '<div class="search-empty">No matching account found.</div>';
      return;
    }

    results.innerHTML = matches.map(g => `
      <div class="search-result-item" onclick="selectAdvanceSearchResult('${escAttr(g.name)}')">
        <span class="search-result-name">${esc(g.name)}</span>
        <span class="search-result-total">Rs. ${g.total.toLocaleString('en-PK')}</span>
      </div>
    `).join('');
  });

  document.addEventListener('click', (e) => {
    if (!wrap.contains(e.target)) box.style.display = 'none';
  });

  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') box.style.display = 'none';
  });
}

function selectAdvanceSearchResult(name) {
  document.getElementById('advanceSearchBox').style.display = 'none';
  filterByAdvancePerson(name);
}

/* ---- Grouped by the Other Name field ---- */
function getAdvanceGroups() {
  const groups = {};
  advanceRecords.forEach(r => {
    const key = r.otherName.trim().toLowerCase();
    if (!groups[key]) groups[key] = { name: r.otherName.trim(), total: 0, count: 0 };
    if (!r.struck) groups[key].total += r.amountRemaining;
    groups[key].count += 1;
  });
  // Keep insertion order (newest entry first) instead of sorting by total.
  return Object.values(groups);
}

function renderAdvanceAccounts() {
  const area  = document.getElementById('advanceAccountsArea');
  const badge = document.getElementById('advanceStudentCountBadge');
  const groups = getAdvanceGroups();

  badge.textContent = groups.length + ' Tasks';

  if (groups.length === 0) {
    area.innerHTML = '<div class="empty-state">No tasks yet.</div>';
    return;
  }

  let html = '<div class="student-grid">';
  groups.forEach(g => {
    const isActive = advanceCurrentFilter && advanceCurrentFilter.toLowerCase() === g.name.toLowerCase();
    html += `<div class="student-account-card${isActive ? ' active' : ''}">
      <div class="student-account-name">${esc(g.name)}</div>
      <div class="student-account-meta">${g.count} ${g.count === 1 ? 'entry' : 'entries'}</div>
      <div class="student-account-total">Rs. ${g.total.toLocaleString('en-PK')}</div>
      <div class="student-account-actions">
        <button class="btn-view" onclick="filterByAdvancePerson('${escAttr(g.name)}')">View List</button>
        <button class="btn-student-download" onclick="downloadAdvancePersonPDF('${escAttr(g.name)}')">Download</button>
      </div>
    </div>`;
  });
  html += '</div>';
  area.innerHTML = html;
}

function filterByAdvancePerson(name) {
  advanceCurrentFilter = name;
  renderAdvanceAccounts();
  renderAdvanceTable();
  document.getElementById('advanceTableArea').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function clearAdvanceFilter() {
  advanceCurrentFilter = null;
  renderAdvanceAccounts();
  renderAdvanceTable();
}

function renderAdvanceTable() {
  const area     = document.getElementById('advanceTableArea');
  const badge    = document.getElementById('advanceCountBadge');
  const bar      = document.getElementById('advanceTotalBar');
  const dlBtn    = document.getElementById('advanceDownloadAllBtn');
  const clearBtn = document.getElementById('advanceClearFilterBtn');
  const titleEl  = document.getElementById('advanceRecordsTitle');
  const totalLabelEl = document.getElementById('advanceTotalLabel');

  const visible = advanceCurrentFilter
    ? advanceRecords.filter(r => r.otherName.trim().toLowerCase() === advanceCurrentFilter.toLowerCase())
    : advanceRecords;

  if (advanceCurrentFilter) {
    titleEl.textContent = advanceCurrentFilter + "'s Task Records";
    totalLabelEl.textContent = advanceCurrentFilter + "'s Total Remaining";
    if (clearBtn) clearBtn.style.display = 'inline-block';
    dlBtn.textContent = 'Download ' + advanceCurrentFilter + "'s Receipt";
    dlBtn.onclick = () => downloadAdvancePersonPDF(advanceCurrentFilter);
  } else {
    titleEl.textContent = 'Task History';
    totalLabelEl.textContent = 'Total Remaining';
    if (clearBtn) clearBtn.style.display = 'none';
    dlBtn.textContent = 'Download All Receipt';
    dlBtn.onclick = () => downloadAdvanceAllPDF();
  }

  badge.textContent = visible.length + ' Records';

  if (visible.length === 0) {
    area.innerHTML = '<div class="empty-state">No records added yet.</div>';
    bar.style.display = 'none';
    dlBtn.style.display = 'none';
    return;
  }

  const total = visible.reduce((s, r) => s + (r.struck ? 0 : r.amountRemaining), 0);
  document.getElementById('advanceTotalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
  bar.style.display = 'flex';
  dlBtn.style.display = 'inline-block';

  let rows = '';
  visible.forEach((r, i) => {
    const serial = visible.length - i;
    rows += `<tr>
      <td class="td-muted">${serial}</td>
      <td class="td-bold">${esc(r.name)}</td>
      <td>${esc(r.otherName)}</td>
      <td class="td-amount td-amount-taken${r.struck ? ' struck-amount' : ''}">Rs. ${r.amountTaken.toLocaleString('en-PK')}</td>
      <td class="td-amount td-amount-price${r.struck ? ' struck-amount' : ''}">Rs. ${advGetPrice(r).toLocaleString('en-PK')}</td>
      <td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amountRemaining.toLocaleString('en-PK')}</td>
      <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
      <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="toggleAdvanceStrike(${r.id})" title="Mark as settled"/></td>
      <td><button class="btn-del" onclick="deleteAdvanceRecord(${r.id})">Delete</button></td>
    </tr>`;
  });

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>Name</th><th>Other Name</th><th>Amount Taken</th><th>Amount Price</th><th>Amount Remaining</th><th>Reason</th><th>Date / Time</th><th>Paid</th><th></th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

function toggleAdvanceStrike(id) {
  const r = advanceRecords.find(x => x.id === id);
  if (!r) return;
  r.struck = !r.struck;
  saveAdvance();
  renderAdvanceTable();
  renderAdvanceAccounts();
}

/* ---- PDF for advance accounts ---- */
function downloadAdvanceAllPDF() {
  const list = advanceCurrentFilter
    ? advanceRecords.filter(r => r.otherName.trim().toLowerCase() === advanceCurrentFilter.toLowerCase())
    : advanceRecords;
  const title = advanceCurrentFilter ? advanceCurrentFilter + "'s Task Receipt" : 'Tasks Receipt';
  const filePrefix = advanceCurrentFilter ? advanceCurrentFilter.replace(/\s+/g, '_') + '_Task_Receipt' : 'Task_Receipt_list_FM';
  buildAdvancePDF(list, title, filePrefix);
}

function downloadAdvancePersonPDF(personName) {
  const list = advanceRecords.filter(r => r.otherName.trim().toLowerCase() === personName.toLowerCase());
  if (list.length === 0) return;
  const title = personName + "'s Task Receipt";
  const filePrefix = personName.replace(/\s+/g, '_') + '_Task_Receipt';
  buildAdvancePDF(list, title, filePrefix);
}

function buildAdvancePDF(recordsList, titleText, filenamePrefix) {
  if (recordsList.length === 0) return;

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const W      = doc.internal.pageSize.getWidth();
  const H      = doc.internal.pageSize.getHeight();
  const margin = 14;
  const today  = new Date().toLocaleDateString('en-PK');
  const total  = recordsList.reduce((s, r) => s + (r.struck ? 0 : r.amountRemaining), 0);

  // Columns: #, Name, Other Name, Taken, Price, Remaining, Date/Time, Reason
  const cols = [
    { x: margin,       w: 7  },
    { x: margin + 7,   w: 24 },
    { x: margin + 31,  w: 24 },
    { x: margin + 55,  w: 21 },
    { x: margin + 76,  w: 21 },
    { x: margin + 97,  w: 23 },
    { x: margin + 120, w: 24 },
    { x: margin + 144, w: W - margin - 144 - margin }
  ];
  const headers = ['No.', 'Name', 'Other Name', 'Taken', 'Price', 'Remaining', 'Date / Time', 'Reason'];

  function pageHeader(isFirst) {
    drawReceiptHeader(doc, W, isFirst, titleText, today);
  }

  pageHeader(true);

  doc.setFillColor(255, 245, 245);
  doc.setDrawColor(200, 180, 180);
  doc.setLineWidth(0.4);
  doc.roundedRect(margin, 33, W - margin * 2, 12, 2, 2, 'FD');
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.text('Total Records: ' + recordsList.length, margin + 4, 41);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(0, 110, 182);
  doc.setFontSize(9);
  doc.text('Total Remaining: Rs. ' + total.toLocaleString('en-PK'), W - margin - 4, 41, { align: 'right' });

  let y = 52;

  function drawTableHeader() {
    doc.setFillColor(235, 235, 235);
    doc.rect(margin, y, W - margin * 2, 8, 'F');
    doc.setDrawColor(170, 170, 170);
    doc.setLineWidth(0.3);
    doc.rect(margin, y, W - margin * 2, 8, 'S');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(60, 60, 60);
    headers.forEach((h, i) => doc.text(h, cols[i].x + 2, y + 5.5));
    y += 10;
  }

  drawTableHeader();

  const orderedRecords = [...recordsList].reverse();
  orderedRecords.forEach((r, idx) => {
    doc.setFontSize(7.5);
    const reasonLines = wrapMultiline(doc, r.reason, cols[7].w - 4);
    const rowH = Math.max(9, reasonLines.length * 4.5 + 3);

    if (y + rowH > H - 20) {
      drawPageFooter();
      doc.addPage();
      pageHeader(false);
      y = 24;
      drawTableHeader();
    }

    const bg = idx % 2 === 0 ? [255, 255, 255] : [249, 249, 249];
    doc.setFillColor(...bg);
    doc.rect(margin, y, W - margin * 2, rowH, 'F');
    doc.setDrawColor(215, 215, 215);
    doc.setLineWidth(0.2);
    doc.line(margin, y + rowH, W - margin, y + rowH);

    const midY = y + rowH / 2 + 1.5;

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.text(String(idx + 1), cols[0].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    doc.text(doc.splitTextToSize(r.name, cols[1].w - 4), cols[1].x + 2, midY);

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(50, 50, 50);
    doc.text(doc.splitTextToSize(r.otherName, cols[2].w - 4), cols[2].x + 2, midY);

    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(139, 38, 38);
    const takenText = 'Rs. ' + r.amountTaken.toLocaleString('en-PK');
    doc.text(takenText, cols[3].x + 2, midY);
    if (r.struck) {
      const tw = doc.getTextWidth(takenText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[3].x + 2, midY - 1.3, cols[3].x + 2 + tw, midY - 1.3);
    }

    doc.setFont('helvetica', r.struck ? 'italic' : 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(22, 128, 60);
    const priceText = 'Rs. ' + advGetPrice(r).toLocaleString('en-PK');
    doc.text(priceText, cols[4].x + 2, midY);
    if (r.struck) {
      const pw = doc.getTextWidth(priceText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[4].x + 2, midY - 1.3, cols[4].x + 2 + pw, midY - 1.3);
    }

    doc.setFont('helvetica', r.struck ? 'italic' : 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(0, 110, 182);
    const remainingText = 'Rs. ' + r.amountRemaining.toLocaleString('en-PK');
    doc.text(remainingText, cols[5].x + 2, midY);
    if (r.struck) {
      const rw = doc.getTextWidth(remainingText);
      doc.setDrawColor(0, 0, 0);
      doc.setLineWidth(0.35);
      doc.line(cols[5].x + 2, midY - 1.3, cols[5].x + 2 + rw, midY - 1.3);
    }

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(100, 100, 100);
    doc.text(r.date, cols[6].x + 2, y + rowH / 2 - 0.5);
    doc.text(r.time, cols[6].x + 2, y + rowH / 2 + 4);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(26, 26, 26);
    const reasonTopY = y + (rowH - reasonLines.length * 4.5) / 2 + 3;
    doc.text(reasonLines, cols[7].x + 2, reasonTopY);

    y += rowH;
  });

  drawPageFooter();
  trackEvent('file_download', { file_extension: 'pdf', section: 'tasks' });
  doc.save(filenamePrefix + '_' + today.replace(/\//g, '-') + '.pdf');

  function drawPageFooter() {
    doc.setDrawColor(26, 58, 92);
    doc.setLineWidth(0.4);
    doc.line(margin, H - 12, W - margin, H - 12);
    doc.setTextColor(140, 140, 140);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7);
    doc.text('Copyright © 2026 FM Register — ' + today, W / 2, H - 7, { align: 'center' });
  }
}

/* ============================================================
   MAIN EXTRA — "Main 1" and "Main 2"
   Two more copies of the "Main" (My Account) page. Each one works
   exactly like Main: add entry, "People I Pay Back" cards, search,
   history table, tick-as-paid, Delete -> Trash (with Restore), and
   Download All Receipt (all / per person).
   Every copy keeps its OWN data in its own Firestore field, and has
   its own section inside Trash, so nothing is mixed with Main.
   ============================================================ */
const EXTRA_DEFS = [
  { id: 'ex1', label: 'Take back', field: 'myExtra1Debt', btnId: 'menuMain1Btn', itemMode: true, takeBack: true },
  { id: 'ex2', label: 'Item Return', field: 'myExtra2Debt', btnId: 'menuMain2Btn', itemMode: true },
  { id: 'ex3', label: 'Note', field: 'myExtra3Debt', btnId: 'menuNoteBtn', itemMode: true, noteMode: true }
];
const EX = {};   // EX.ex1 / EX.ex2 — also used by the inline onclick handlers below

function createExtraAccount(def) {
  const key   = def.id;                              // 'ex1' | 'ex2'  (also the trash _type)
  const label = def.label;                           // 'Main 1' | 'Main 2'
  const fileLabel = label.replace(/\s+/g, '_');      // 'Main_1'
  const itemMode = !!def.itemMode;                   // no amounts, item wording
  const takeBack = !!def.takeBack;                   // 'Take back' page wording
  const noteMode = !!def.noteMode;                   // 'Note' page: only a note text, auto-named Note 1, Note 2...
  let records = [];                                  // same shape as ownRecords
  let currentFilter = null;
  const api = {};

  const $ = (suffix) => document.getElementById(key + suffix);
  const attr = (s) => escAttr(s).replace(/"/g, '&quot;');

  /* ---------- page markup (same layout as the Main page) ---------- */
  document.body.insertAdjacentHTML('beforeend', `
  <div class="myself-page" id="${key}Page" style="display:none;">
    <div class="myself-page-inner">
      <div class="myself-page-header">
        <h1>${noteMode ? 'My Text Note' : (takeBack ? 'take back item' : label)}</h1>
        <div class="myself-header-actions">
          <div class="header-search" id="${key}SearchWrap">
            <button class="search-icon-btn-light" id="${key}SearchToggleBtn" type="button" aria-label="Search ${label}">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            </button>
            <div class="search-box" id="${key}SearchBox" style="display:none;">
              <input type="text" id="${key}SearchInput" placeholder="Search by name..." autocomplete="off"/>
              <div class="search-results" id="${key}SearchResults"></div>
            </div>
          </div>
          <button class="btn-close-myself" id="${key}CloseBtn" type="button">Close ✕</button>
        </div>
      </div>

      <section class="card rcv-card">
        <div class="rcv-top">
          <div class="rcv-title">
            <span class="rcv-wallet" aria-hidden="true">${RCV_ICONS[noteMode ? 'note' : (takeBack ? 'undo' : (itemMode ? 'box' : 'home'))]}</span>
            <div class="rcv-heading">
              <div class="receivables-label">${label}:</div>
              <h2 class="section-title">${noteMode ? 'My Notes' : (takeBack ? 'take back my item' : (itemMode ? 'Return an item' : 'My Loans'))}</h2>
            </div>
          </div>
        </div>

        <div class="field rcv-field" style="--i:0">
          <label class="rcv-label" for="${key}FromName">${RCV_ICONS.user}${noteMode ? 'Collection' : (takeBack ? 'Boiz name' : (itemMode ? 'Received From Boiz name' : 'Received From'))}</label>
          <input type="text" id="${key}FromName" placeholder="${noteMode ? 'Collection name ' : "Person's name"}"/>
        </div>

        ${itemMode ? `
        <div class="field rcv-field" style="--i:1">
          <label class="rcv-label" for="${key}Reason">${RCV_ICONS.doc}${noteMode ? 'Add Note' : 'Purpose / Reason'}</label>
          <textarea id="${key}Reason" rows="${noteMode ? 3 : 2}" placeholder="${noteMode ? 'Type Note Text' : (takeBack ? 'For what was that item being returned?' : 'What was the return of the item for?')}"></textarea>
        </div>

        <div class="grid-2">
          <div class="field rcv-field" style="--i:2">
            <label class="rcv-label" for="${key}Date">${RCV_ICONS.cal}Date</label>
            <input type="date" id="${key}Date"/>
          </div>
          <div class="field rcv-field" style="--i:3">
            <label class="rcv-label" for="${key}Time">${RCV_ICONS.clock}Time</label>
            <input type="time" id="${key}Time"/>
          </div>
        </div>
        ` : `
        <div class="grid-3">
          <div class="field rcv-field" style="--i:1">
            <label class="rcv-label" for="${key}Amount">${RCV_ICONS.money}Amount (Rs.)</label>
            <input type="number" id="${key}Amount" placeholder="Rs. 0" min="1"/>
          </div>
          <div class="field rcv-field" style="--i:2">
            <label class="rcv-label" for="${key}Date">${RCV_ICONS.cal}Date</label>
            <input type="date" id="${key}Date"/>
          </div>
          <div class="field rcv-field" style="--i:3">
            <label class="rcv-label" for="${key}Time">${RCV_ICONS.clock}Time</label>
            <input type="time" id="${key}Time"/>
          </div>
        </div>

        <div class="field rcv-field" style="--i:4">
          <label class="rcv-label" for="${key}Reason">${RCV_ICONS.doc}Purpose / Reason</label>
          <textarea id="${key}Reason" rows="2" placeholder="What the money was for"></textarea>
        </div>
        `}

        <button class="rcv-add-btn" id="${key}SubmitBtn" type="button">
          <span class="rcv-add-plus" aria-hidden="true">${RCV_ICONS.plus}</span>
          Add Entry
        </button>
        ${rcvWavesHTML()}
      </section>

      <section class="card">
        <div class="records-header">
          <div>
            <h2 class="section-title">${noteMode ? 'My Notes List' : (takeBack ? 'Take back from' : (itemMode ? 'People I return Back' : 'People I Pay Back'))}</h2>
            <span class="count-badge" id="${key}StudentCountBadge">${noteMode ? '0 Notes' : '0 People'}</span>
          </div>
        </div>
        <div id="${key}AccountsArea"></div>
      </section>

      <section class="card">
        <div class="records-header">
          <div>
            <h2 class="section-title" id="${key}RecordsTitle">${noteMode ? 'My Notes History' : 'My Loan History'}</h2>
            <span class="count-badge" id="${key}CountBadge">0 Records</span>
          </div>
          <div class="records-header-actions">
            <button class="btn-download-all" id="${key}DownloadAllBtn" style="display:none;">Download All Receipt</button>
          </div>
        </div>

        <div id="${key}TableArea"></div>

        <div class="total-bar" id="${key}TotalBar" style="display:none;">
          <span class="total-label" id="${key}TotalLabel">Total Borrowed</span>
          <span class="total-value" id="${key}TotalAmount">Rs. 0</span>
        </div>
      </section>
    </div>
  </div>`);
  decoratePageHeader(document.getElementById(key + 'Page'));
  decorateRecordCards(document.getElementById(key + 'Page'));

  /* ---------- data ---------- */
  function save() {
    if (!currentAccountKey) return;
    accountDocRef(currentAccountKey).set({ [def.field]: records }, { merge: true })
      .catch(err => console.error('Save failed:', err));
  }

  function addRecord() {
    const from    = noteMode ? ($('FromName').value.trim() || ('Note ' + nextNoteNumber())) : $('FromName').value.trim();
    const amount  = itemMode ? 0 : parseFloat($('Amount').value);
    const date    = $('Date').value;
    const time    = convertTo12hr($('Time').value);
    const reason  = $('Reason').value.trim();

    if (!from)   { alert(itemMode ? 'Plz enter who you received from.' : 'Plz enter who you borrowed from.'); return; }
    if (!itemMode && (!amount || amount <= 0)) { alert('Plz enter a valid amount.'); return; }
    if (!date)   { alert('Plz select a date.'); return; }
    if (!reason) { alert(noteMode ? 'Plz type the note text.' : 'Plz enter a reason.'); return; }

    records.unshift({ id: Date.now(), from, amount, date, time, reason });
    save();
    renderAccounts();
    renderTable();
    resetForm();
    trackEvent('add_entry', { section: key });
    showToast();
  }

  // Note account: every new entry becomes its own account -> Note 1, Note 2, Note 3 ...
  // (numbers never repeat, even if an earlier note is sitting in Trash)
  function nextNoteNumber() {
    let max = 0;
    const scan = (r) => {
      const m = /^Note (\d+)$/i.exec(String(r.from || '').trim());
      if (m) max = Math.max(max, parseInt(m[1], 10));
    };
    records.forEach(scan);
    trashItems.filter(t => t._type === key).forEach(scan);
    return max + 1;
  }

  function resetForm() {
    if (!itemMode) $('Amount').value = '';
    if (noteMode) $('FromName').value = '';
    $('Reason').value = '';
    const now = new Date();
    $('Date').value = now.toISOString().split('T')[0];
    $('Time').value = now.toTimeString().slice(0, 5);
  }

  // Delete -> goes to Trash first (its own "Main 1" / "Main 2" section)
  function del(rid) {
    if (!confirm('Move this record to Trash?')) return;
    const r = records.find(x => x.id === rid);
    if (!r) return;
    records = records.filter(x => x.id !== rid);
    trashItems.unshift({ ...r, _type: key });
    save();
    saveTrash();
    renderAccounts();
    renderTable();
  }

  // Called from the Trash page when "Restore" is pressed
  api.restore = function (clean) {
    records.unshift(clean);
    save();
    renderAccounts();
    renderTable();
  };

  function toggleStrike(rid) {
    const r = records.find(x => x.id === rid);
    if (!r) return;
    r.struck = !r.struck;
    save();
    renderTable();
    renderAccounts();
  }

  /* ---------- people cards ---------- */
  function getGroups() {
    const groups = {};
    records.forEach(r => {
      const k = r.from.trim().toLowerCase();
      if (!groups[k]) groups[k] = { name: r.from.trim(), total: 0, count: 0 };
      if (!r.struck) groups[k].total += (r.amount || 0);
      groups[k].count += 1;
    });
    return Object.values(groups);   // newest entry first
  }

  function renderAccounts() {
    const area  = $('AccountsArea');
    const badge = $('StudentCountBadge');
    const groups = getGroups();

    badge.textContent = groups.length + (noteMode ? ' Notes' : ' People');

    if (groups.length === 0) {
      area.innerHTML = '<div class="empty-state">' + (noteMode ? 'You have not added any note yet.' : 'You have not added anyone yet.') + '</div>';
      return;
    }

    let html = '<div class="student-grid">';
    groups.forEach(g => {
      const isActive = currentFilter && currentFilter.toLowerCase() === g.name.toLowerCase();
      html += `<div class="student-account-card${isActive ? ' active' : ''}">
        <div class="student-account-name">${esc(g.name)}</div>
        <div class="student-account-meta">${g.count} ${g.count === 1 ? 'entry' : 'entries'}</div>
        ${itemMode ? '' : `<div class="student-account-total">Rs. ${g.total.toLocaleString('en-PK')}</div>`}
        <div class="student-account-actions">
          <button class="btn-view" onclick="EX.${key}.filterByPerson('${attr(g.name)}')">View List</button>
          <button class="btn-student-download" onclick="EX.${key}.downloadPerson('${attr(g.name)}')">Download</button>
        </div>
      </div>`;
    });
    html += '</div>';
    area.innerHTML = html;
  }

  function filterByPerson(name) {
    currentFilter = name;
    renderAccounts();
    renderTable();
    $('TableArea').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  }

  function clearFilter() {
    currentFilter = null;
    renderAccounts();
    renderTable();
  }

  /* ---------- history table ---------- */
  function renderTable() {
    const area     = $('TableArea');
    const badge    = $('CountBadge');
    const bar      = $('TotalBar');
    const dlBtn    = $('DownloadAllBtn');
    const clearBtn = $('ClearFilterBtn');
    const titleEl  = $('RecordsTitle');
    const totalLabelEl = $('TotalLabel');

    const visible = currentFilter
      ? records.filter(r => r.from.trim().toLowerCase() === currentFilter.toLowerCase())
      : records;

    if (currentFilter) {
      titleEl.textContent = (noteMode ? 'Note To ' : 'Repaid ') + currentFilter;
      totalLabelEl.textContent = 'Total Owed to ' + currentFilter;
      if (clearBtn) clearBtn.style.display = 'inline-block';
      dlBtn.textContent = 'Download ' + currentFilter + "'s Receipt";
      dlBtn.onclick = () => downloadPerson(currentFilter);
    } else {
      titleEl.textContent = noteMode ? 'My Notes History' : 'My Loan History';
      totalLabelEl.textContent = 'Total Borrowed';
      if (clearBtn) clearBtn.style.display = 'none';
      dlBtn.textContent = 'Download All Receipt';
      dlBtn.onclick = () => downloadAll();
    }

    badge.textContent = visible.length + ' Records';

    if (visible.length === 0) {
      area.innerHTML = '<div class="empty-state">No records added yet.</div>';
      bar.style.display = 'none';
      dlBtn.style.display = 'none';
      return;
    }

    const total = visible.reduce((s, r) => s + (r.struck ? 0 : (r.amount || 0)), 0);
    $('TotalAmount').textContent = 'Rs. ' + total.toLocaleString('en-PK');
    bar.style.display = itemMode ? 'none' : 'flex';
    dlBtn.style.display = 'inline-block';

    let rows = '';
    visible.forEach((r, i) => {
      const serial = visible.length - i;
      rows += `<tr>
        <td class="td-muted">${serial}</td>
        <td class="td-bold">${esc(r.from)}</td>
        ${itemMode ? '' : `<td class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${(r.amount || 0).toLocaleString('en-PK')}</td>`}
        <td class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
        <td class="td-muted" style="white-space:nowrap;">${r.date} &nbsp; ${r.time}</td>
        <td class="td-check"><input type="checkbox" class="strike-check" ${r.struck ? 'checked' : ''} onchange="EX.${key}.toggleStrike(${r.id})" title="Mark as settled"/></td>
        <td><button class="btn-del" onclick="EX.${key}.del(${r.id})">Delete</button></td>
      </tr>`;
    });

    area.innerHTML = `<div class="table-wrap"><table>
      <thead><tr>
        <th>#</th><th>${noteMode ? 'Collection' : 'Repaid'}</th>${itemMode ? '' : '<th class="th-blue">Amount</th>'}<th>${noteMode ? 'Note' : 'Reason'}</th><th>Date / Time</th><th>Paid</th><th></th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`;
  }

  /* ---------- Download All Receipt (same PDF design as Main) ---------- */
  function pdfOpts() {
    return {
      noAmount: itemMode,
      repayLabel: noteMode ? 'Collection' : (takeBack ? 'Taken back from' : null),
      reasonLabel: noteMode ? 'Note' : null
    };
  }

  function downloadAll() {
    const list = currentFilter
      ? records.filter(r => r.from.trim().toLowerCase() === currentFilter.toLowerCase())
      : records;
    const retWord = noteMode ? 'Note To ' : (takeBack ? 'Item Taken Back ' : (itemMode ? 'Item Return to ' : 'Payment Return to '));
    const title = currentFilter ? retWord + currentFilter : (noteMode ? 'My Notes Receipt' : (takeBack ? 'Item Taken Back' : (itemMode ? label + ' Receipt' : label + ' Loans Receipt')));
    const filePrefix = currentFilter
      ? fileLabel + '_' + currentFilter.replace(/\s+/g, '_') + (noteMode ? '_Receipt' : '_Owed_Receipt')
      : fileLabel + (itemMode ? '_Receipt' : '_Loans_Receipt');
    buildOwnPDF(list, title, filePrefix, pdfOpts());
  }

  function downloadPerson(name) {
    const list = records.filter(r => r.from.trim().toLowerCase() === name.toLowerCase());
    if (list.length === 0) return;
    buildOwnPDF(list, (noteMode ? 'Note To ' : (takeBack ? 'Item Taken Back ' : (itemMode ? 'Item Return to ' : 'Payment Return to '))) + name,
      fileLabel + '_' + name.replace(/\s+/g, '_') + (noteMode ? '_Receipt' : '_Owed_Receipt'), pdfOpts());
  }

  /* ---------- search (only inside this account) ---------- */
  const searchWrap    = $('SearchWrap');
  const searchBox     = $('SearchBox');
  const searchInput   = $('SearchInput');
  const searchResults = $('SearchResults');

  $('SearchToggleBtn').addEventListener('click', () => {
    const isHidden = searchBox.style.display === 'none';
    searchBox.style.display = isHidden ? 'block' : 'none';
    if (isHidden) {
      searchInput.value = '';
      searchResults.innerHTML = '';
      searchInput.focus();
    }
  });

  searchInput.addEventListener('input', () => {
    const q = searchInput.value.trim().toLowerCase();
    if (!q) { searchResults.innerHTML = ''; return; }

    const matches = getGroups().filter(g => g.name.toLowerCase().includes(q));
    if (matches.length === 0) {
      searchResults.innerHTML = '<div class="search-empty">No matching account found.</div>';
      return;
    }
    searchResults.innerHTML = matches.map(g => `
      <div class="search-result-item" onclick="EX.${key}.selectSearch('${attr(g.name)}')">
        <span class="search-result-name">${esc(g.name)}</span>
        ${itemMode ? '' : `<span class="search-result-total">Rs. ${g.total.toLocaleString('en-PK')}</span>`}
      </div>
    `).join('');
  });

  document.addEventListener('click', (e) => {
    if (!searchWrap.contains(e.target)) searchBox.style.display = 'none';
  });
  searchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') searchBox.style.display = 'none';
  });

  /* ---------- wiring ---------- */
  $('SubmitBtn').addEventListener('click', addRecord);
  $('CloseBtn').addEventListener('click', () => api.close());
  if ($('ClearFilterBtn')) $('ClearFilterBtn').addEventListener('click', clearFilter);
  resetForm();

  api.open = function () {
    $('Page').style.display = 'block';
    document.body.style.overflow = 'hidden';
    renderAccounts();
    renderTable();
  };
  api.close = function () {
    $('Page').style.display = 'none';
    document.body.style.overflow = '';
  };
  api.setRecords   = (arr) => { records = Array.isArray(arr) ? arr : []; currentFilter = null; };
  api.resetFilter  = () => { currentFilter = null; };
  api.selectSearch = (name) => { searchBox.style.display = 'none'; filterByPerson(name); };
  api.filterByPerson = filterByPerson;
  api.downloadPerson = downloadPerson;
  api.toggleStrike   = toggleStrike;
  api.del            = del;
  return api;
}

EXTRA_DEFS.forEach(def => { EX[def.id] = createExtraAccount(def); });

// Called when an account is loaded (login / session restore / new sign-up)
function loadExtraRecords(data) {
  EXTRA_DEFS.forEach(d => EX[d.id].setRecords(data && data[d.field]));
}
function resetExtraFilters() {
  EXTRA_DEFS.forEach(d => EX[d.id].resetFilter());
}
function hideExtraPages() {
  EXTRA_DEFS.forEach(d => { document.getElementById(d.id + 'Page').style.display = 'none'; });
}

/* ============================================================
   TRASH — deleted records land here first, split into 3
   portions by where they came from: "Text Note" (main
   Candidate Accounts records), "My Account" (own records),
   and "Tasks" (advance records). Items can be restored or
   removed permanently from this page.
   ============================================================ */
function saveTrash() {
  if (!currentAccountKey) return;
  accountDocRef(currentAccountKey).set({ hostelTrash: trashItems }, { merge: true })
    .catch(err => console.error('Save failed:', err));
}

// Every Trash section: tap the card header -> smooth open / close of its deleted records
function initTrashToggles() {
  document.querySelectorAll('#trashPage .tr-card').forEach(card => {
    const head = card.querySelector('.tr-head');
    head.addEventListener('click', () => {
      const open = !card.classList.contains('open');
      card.classList.toggle('open', open);
      head.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  });
}
initTrashToggles();

function openTrashPage() {
  const page = document.getElementById('trashPage');
  page.style.display = 'block';
  page.scrollTop = 0;
  document.body.style.overflow = 'hidden';
  renderTrash();
}

function closeTrashPage() {
  document.getElementById('trashPage').style.display = 'none';
  document.body.style.overflow = '';
}

function renderTrash() {
  renderTrashPortion('main',    'trashMainArea',     'trashMainCountBadge');
  renderTrashPortion('own',     'trashOwnArea',       'trashOwnCountBadge');
  EXTRA_DEFS.forEach(d => {
    const cap = d.id.charAt(0).toUpperCase() + d.id.slice(1);   // ex1 -> Ex1
    renderTrashPortion(d.id, 'trash' + cap + 'Area', 'trash' + cap + 'CountBadge');
  });
  renderTrashPortion('advance', 'trashAdvanceArea',   'trashAdvanceCountBadge');
}

function renderTrashPortion(type, areaId, badgeId) {
  const area  = document.getElementById(areaId);
  const badge = document.getElementById(badgeId);
  const items = trashItems.filter(r => (r._type || 'main') === type);

  const label = items.length + (items.length === 1 ? ' Item' : ' Items');
  if (badge.textContent !== label) {
    badge.textContent = label;
    badge.classList.remove('bump'); void badge.offsetWidth; badge.classList.add('bump');
  }

  if (items.length === 0) {
    area.innerHTML = '<div class="empty-state">Trash is empty.</div>';
    return;
  }

  const def        = EX[type] ? EXTRA_DEFS.find(d => d.id === type) : null;
  const noAmt      = !!(def && def.itemMode);
  const isNoteType = !!(def && def.noteMode);
  const isAdv      = type === 'advance';

  let rows = '';
  items.forEach((r, i) => {
    const serial   = items.length - i;
    const isOwnShape = type === 'own' || !!EX[type];   // Take back / Item Return / Note use the same record shape as My Account
    const nameCell = isOwnShape ? esc(r.from)
      : isAdv ? (esc(r.name) + ' &rarr; ' + esc(r.otherName))
      : (esc(r.student) + ' &rarr; ' + esc(r.lender));
    const amountVal = isAdv ? r.amountTaken : (r.amount || 0);
    const remainingCell = isAdv
      ? `<td data-label="Amount Price" class="td-amount td-amount-price${r.struck ? ' struck-amount' : ''}">Rs. ${advGetPrice(r).toLocaleString('en-PK')}</td><td data-label="Amount Remaining" class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${r.amountRemaining.toLocaleString('en-PK')}</td>`
      : '';
    rows += `<tr>
      <td data-label="#" class="td-muted td-no"><span class="tr-no">${serial}</span></td>
      <td data-label="${isNoteType ? 'Callback/User' : 'Name'}" class="td-bold td-name">${nameCell}</td>
      ${noAmt ? '' : `<td data-label="${isAdv ? 'Amount Taken' : 'Amount'}" class="td-amount${r.struck ? ' struck-amount' : ''}">Rs. ${amountVal.toLocaleString('en-PK')}</td>`}
      ${remainingCell}
      <td data-label="${isNoteType ? 'Note' : 'Reason'}" class="td-reason" title="${esc(r.reason)}" onclick="this.classList.toggle('reason-expanded')">${esc(r.reason)}</td>
      <td data-label="Date / Time" class="td-muted td-when">${r.date} &nbsp; ${r.time}</td>
      <td data-label="Action" class="td-actions">
        <div class="tr-actions">
          <button class="btn-view btn-restore" type="button" onclick="trashAct(this,'restore',${r.id})">Restore</button>
          <button class="btn-del" type="button" onclick="trashAct(this,'del',${r.id})">Delete Forever</button>
        </div>
      </td>
    </tr>`;
  });

  const amountHeader = isAdv ? '<th>Amount Taken</th><th>Amount Price</th><th>Amount Remaining</th>' : (noAmt ? '' : '<th class="th-blue">Amount</th>');

  area.innerHTML = `<div class="table-wrap"><table>
    <thead><tr>
      <th>#</th><th>${isNoteType ? 'Callback/User' : 'Name'}</th>${amountHeader}<th>${isNoteType ? 'Note' : 'Reason'}</th><th>Date / Time</th><th class="th-action">Action</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table></div>`;
}

// Restore / Delete Forever with a short exit animation on the row before the data changes
function trashAct(btn, kind, id) {
  if (kind === 'del' && !confirm('Permanently delete this record? This cannot be undone.')) return;
  const row = btn.closest('tr');
  const run = () => (kind === 'del' ? deleteForeverFromTrash(id, true) : restoreFromTrash(id));
  if (!row || window.matchMedia('(prefers-reduced-motion: reduce)').matches) { run(); return; }
  row.querySelectorAll('button').forEach(b => b.disabled = true);
  row.classList.add(kind === 'del' ? 'tr-leave-del' : 'tr-leave-restore');
  setTimeout(run, 380);
}

function restoreFromTrash(id) {
  const item = trashItems.find(x => x.id === id);
  if (!item) return;
  trashItems = trashItems.filter(x => x.id !== id);
  const { _type, ...clean } = item;
  if (_type === 'own') {
    ownRecords.unshift(clean);
    saveOwn();
    renderOwnAccounts();
    renderOwnTable();
  } else if (EX[_type]) {
    EX[_type].restore(clean);
  } else if (_type === 'advance') {
    advanceRecords.unshift(clean);
    saveAdvance();
    renderAdvanceAccounts();
    renderAdvanceTable();
  } else {
    records.unshift(clean);
    save();
    renderStudentAccounts();
    renderTable();
  }
  saveTrash();
  renderTrash();
}

function deleteForeverFromTrash(id, skipConfirm) {
  if (!skipConfirm && !confirm('Permanently delete this record? This cannot be undone.')) return;
  trashItems = trashItems.filter(x => x.id !== id);
  saveTrash();
  renderTrash();
}


/* ============================================================
   PHONE TABLES — every record table (Receivables, Main, Tasks,
   Items, Note ...) turns into stacked cards on small screens.
   The cards need a label per cell, so each cell takes its label
   from the column heading whenever a table is (re)drawn.
   (Trash builds its own labels in renderTrashPortion.)
   ============================================================ */
(function () {
  let queued = false;
  function labelTables() {
    queued = false;
    document.querySelectorAll('.table-wrap table').forEach(tbl => {
      if (tbl.closest('#trashPage')) return;
      const heads = Array.from(tbl.querySelectorAll('thead th')).map(th => th.textContent.trim());
      tbl.querySelectorAll('tbody tr').forEach(tr => {
        if (tr.dataset.labeled) return;
        tr.dataset.labeled = '1';
        Array.from(tr.cells).forEach((td, i) => {
          td.setAttribute('data-label', heads[i] || '');
          if (!heads[i] && td.querySelector('button')) td.classList.add('td-act');
        });
      });
    });
  }
  function queue() { if (!queued) { queued = true; requestAnimationFrame(labelTables); } }
  new MutationObserver(queue).observe(document.body, { childList: true, subtree: true });
  queue();
})();


/* ============================================================
   TRASH TABLES ON PHONES — same table as on a laptop; if it is
   wider than the screen it is shrunk to fit (no sideways scroll,
   nothing moves to another place).
   ============================================================ */
(function () {
  let queued = false;
  function fit() {
    queued = false;
    document.querySelectorAll('#trashPage .table-wrap table').forEach(t => {
      const wrap = t.parentElement;
      t.style.zoom = '';
      const avail = wrap.clientWidth;
      if (!avail) return;
      const prev = t.style.width;
      t.style.width = 'max-content';
      const need = t.offsetWidth;
      t.style.width = prev;
      if (need > avail) t.style.zoom = String(Math.max(0.4, avail / need));
    });
  }
  function queue() { if (!queued) { queued = true; requestAnimationFrame(fit); } }
  new MutationObserver(queue).observe(document.getElementById('trashPage'), { childList: true, subtree: true });
  window.addEventListener('resize', queue);
  window.addEventListener('orientationchange', queue);
})();
